export function normalizeAttachmentContentType(type) {
    return type?.split(";")[0].trim().toLowerCase();
}
export const isJsonAttachmentContentType = (type) => {
    const normalized = normalizeAttachmentContentType(type);
    return normalized === "application/json" || normalized === "text/json" || normalized.endsWith("+json");
};
export const isHtmlAttachmentContentType = (type) => {
    const normalized = normalizeAttachmentContentType(type);
    return normalized === "text/html" || normalized === "application/xhtml+xml";
};
